#!/usr/bin/env node
// ios-postsync.mjs — apply native iOS tweaks that live in the generated ios/
// project (which is .gitignored, so we re-apply them after every cap sync/copy
// instead of hand-editing files that get regenerated). Idempotent. macOS only.
//
// - hide the status bar at the OS level, from the splash onward, so there is no
//   top strip even before the WebView's JS runs (complements the runtime
//   StatusBar.hide() in src/mobile.js — belt and suspenders).
// - install the committed app icon + splash masters (assets/ios/, generated by
//   tools/gen-app-assets.sh) into the .gitignored ios/ asset catalog, since the
//   catalog is regenerated by `cap add ios` and would otherwise revert to the
//   default Capacitor placeholders.
//
// Usage: node tools/ios-postsync.mjs   (run by `npm run copy` / `npm run sync`)

import { execFileSync } from 'node:child_process';
import { copyFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const ASSETS = join(ROOT, 'assets', 'ios');
const XCASSETS = join(ROOT, 'ios', 'App', 'App', 'Assets.xcassets');
const PLIST = join(ROOT, 'ios', 'App', 'App', 'Info.plist');
const PB = '/usr/libexec/PlistBuddy';

function log(...a) { console.log('[ios-postsync]', ...a); }

// Copy our brand masters into the asset catalog. Filenames match the catalog's
// Contents.json (the splash imageset reuses one 2732 image for 1x/2x/3x).
function installAssets() {
  const icon = join(ASSETS, 'icon-1024.png');
  const splash = join(ASSETS, 'splash-2732.png');
  if (!existsSync(icon) || !existsSync(splash)) {
    log('skip assets: masters missing — run `bash tools/gen-app-assets.sh`');
    return;
  }
  const copies = [
    [icon, join(XCASSETS, 'AppIcon.appiconset', 'AppIcon-512@2x.png')],
    [splash, join(XCASSETS, 'Splash.imageset', 'splash-2732x2732.png')],
    [splash, join(XCASSETS, 'Splash.imageset', 'splash-2732x2732-1.png')],
    [splash, join(XCASSETS, 'Splash.imageset', 'splash-2732x2732-2.png')],
  ];
  for (const [src, dst] of copies) {
    if (!existsSync(dirname(dst))) continue; // catalog not generated yet
    copyFileSync(src, dst);
    log('installed', dst.slice(ROOT.length + 1));
  }
}

installAssets();

if (!existsSync(PLIST)) {
  log('skip: ios/ not generated yet (run `npm run ios:add` first) —', PLIST);
  process.exit(0);
}
if (!existsSync(PB)) {
  log('skip: PlistBuddy not found (not macOS?) —', PB);
  process.exit(0);
}

// Set a bool key, adding it if missing (Set fails on a non-existent key).
function setBool(key, value) {
  const v = value ? 'true' : 'false';
  try {
    execFileSync(PB, ['-c', `Set :${key} ${v}`, PLIST], { stdio: 'pipe' });
  } catch (_) {
    execFileSync(PB, ['-c', `Add :${key} bool ${v}`, PLIST], { stdio: 'pipe' });
  }
  log(`set ${key} = ${v}`);
}

// Status bar hidden from launch; opt out of per-view-controller appearance so
// the Info.plist value actually wins.
setBool('UIStatusBarHidden', true);
setBool('UIViewControllerBasedStatusBarAppearance', false);

log('done →', PLIST);
